"""Offline registry acceptance. Generated bytes are not original-source proof."""
import json
import shutil
import subprocess
import sys

import pytest

from aql.warehouse.registry import history
from aql.warehouse.storage import canonical, seal
from tests.test_warehouse import fixture, warehouse, START, KEY, DAY


def populate(path, **kwargs):
    w = warehouse(path)
    raw, check = fixture(count=15, **kwargs)
    with w.writer():
        w.import_archive(raw, check, KEY, observed_ms=START+DAY)
    return w, raw, check


def test_deterministic_rebuild_restart_replay_and_consumer(tmp_path):
    w, raw, check = populate(tmp_path/'first')
    before = w.report()['registry']
    with w.writer():
        assert w.rebuild_registry() == before
        result = w.import_archive(raw, check, KEY, observed_ms=START+2*DAY)
        assert result['inserted_rows'] == 0
        assert w.rebuild_registry() == before
    shutil.copytree(tmp_path/'first', tmp_path/'copy')
    # Relocation of identical evidence has the same snapshot; no absolute root
    # or wall clock enters its identity. Read does not modify policy or storage.
    assert warehouse(tmp_path/'copy').report()['registry'] == before
    code = '''import json,sys
from aql.warehouse.engine import HistoricalWarehouse
w=HistoricalWarehouse(sys.argv[1],reserve=0,test_root=True)
print(json.dumps(w.query('15m',int(sys.argv[2]),int(sys.argv[2])+900000,
cutoff_ms=int(sys.argv[2])+86400000,include_registry=True)))
'''
    read = subprocess.run([sys.executable, '-c', code, str(w.root), str(START)],
                          capture_output=True, text=True, check=True)
    result = json.loads(read.stdout)
    assert result['registry'] == before and len(result['bars']) == 1
    assert before['event_watermark'] == 1 and before['physical_rows'] == 15
    assert before['projected_intervals']['15m'] == 1
    assert before['projections_physically_stored'] is False
    assert before['scientific_status'] == 'REAL_PIT_OOS_BLOCKED'
    assert before['forward_status'] == 'FORWARD_UNQUALIFIED'
    assert before['trading_authority'] == 'NONE'


@pytest.mark.parametrize('fault', ['missing_event', 'tampered_event', 'missing_lineage',
                                  'bad_source_identity', 'bad_raw', 'bad_snapshot', 'missing_shard'])
def test_corruption_fails_closed(tmp_path, fault):
    w, raw, check = populate(tmp_path)
    event = tmp_path/'catalog/registry/event-000000000001.json'
    source = tmp_path/f'catalog/{seal(raw)}.json'
    if fault == 'missing_event':
        event.unlink()
    elif fault == 'tampered_event':
        event.write_bytes(event.read_bytes()+b'x')
    elif fault == 'missing_lineage':
        source.unlink()
    elif fault == 'bad_source_identity':
        body = json.loads(source.read_bytes())
        body['source_zip_sha256'] = '0'*64
        source.write_bytes(canonical(body))
    elif fault == 'bad_raw':
        (tmp_path/f'raw/{seal(raw)}.zip').write_bytes(raw+b'x')
    elif fault == 'bad_snapshot':
        next((tmp_path/'catalog/registry').glob('snapshot-*.json')).write_bytes(b'{}')
    else:
        next((tmp_path/'bars').glob('????-??-??.sqlite')).unlink()
    with pytest.raises((ValueError, FileNotFoundError)):
        w.query('15m', START, START+900000, cutoff_ms=START+DAY, include_registry=True)


@pytest.mark.parametrize('seam', ['source_commit', 'event_commit', 'checkpoint_commit'])
def test_interrupted_registry_suffix_recovers_without_double_count(tmp_path, monkeypatch, seam):
    w = warehouse(tmp_path)
    raw, check = fixture(count=15)
    write = w.write_once
    def crash(relative, data):
        target = {'source_commit':'catalog/registry/event-',
                  'event_commit':'catalog/registry/checkpoint-',
                  'checkpoint_commit':'catalog/registry/snapshot-'}[seam]
        if relative.startswith(target):
            raise OSError('TEST_POWER_LOSS')
        return write(relative, data)
    with w.writer():
        monkeypatch.setattr(w, 'write_once', crash)
        with pytest.raises(OSError, match='POWER_LOSS'):
            w.import_archive(raw, check, KEY, observed_ms=START+DAY)
    with pytest.raises(ValueError):
        warehouse(tmp_path).report()
    with warehouse(tmp_path).writer() as recovered:
        snapshot = recovered.rebuild_registry()
        recovered.import_archive(raw, check, KEY, observed_ms=START+2*DAY)
        assert recovered.report()['registry'] == snapshot
        assert snapshot['physical_rows'] == 15
        assert len([e for e in history(recovered) if e['event_type'] == 'SOURCE_COMMITTED']) == 1


def test_gap_repair_rejections_and_recovery_are_visible(tmp_path):
    w, raw, check = populate(tmp_path, missing=(7,))
    assert w.report()['registry']['internal_gaps'] == [[START+7*60000, START+8*60000]]
    with w.writer():
        bad, checksum = fixture(count=15, changed=2)
        with pytest.raises(ValueError, match='SOURCE_BAR_CONFLICT'):
            w.import_archive(bad, checksum, KEY, observed_ms=START+DAY)
        complete, checksum = fixture(count=15)
        w.import_archive(complete, checksum, KEY, observed_ms=START+DAY)
        assert not w.report()['registry']['internal_gaps']
    next((tmp_path/'bars').glob('????-??-??.sqlite')).unlink()
    with w.writer():
        w.import_archive(complete, checksum, KEY, observed_ms=START+DAY)
        kinds = [e['event_type'] for e in history(w)]
        assert 'SOURCE_REJECTED_QUARANTINED' in kinds and 'REPAIR_RECOVERY' in kinds
        assert w.report()['registry']['physical_rows'] == 15


def test_quarantine_bytes_have_verified_event_identity(tmp_path):
    w = warehouse(tmp_path)
    bad = b'CORRUPT_GENERATED_SOURCE'
    with w.writer():
        name = f"quarantine/{'0'*64}-{seal(bad)}.zip"
        w.write_once(name, bad)
        state = w.rebuild_registry()
        assert state['event_watermark'] == 1
        assert history(w)[0]['event_type'] == 'CORRUPT_SOURCE_QUARANTINED'
    (tmp_path/name).write_bytes(b'TAMPERED')
    with pytest.raises(ValueError, match='QUARANTINE_DIGEST'):
        w.report()


def test_shard_without_source_receipt_is_never_research_eligible(tmp_path, monkeypatch):
    w = warehouse(tmp_path)
    raw, check = fixture(count=15)
    write = w.write_once
    def crash(relative, data):
        if relative == f'catalog/{seal(raw)}.json':
            raise OSError('TEST_CATALOG_LOSS')
        return write(relative, data)
    with w.writer():
        monkeypatch.setattr(w, 'write_once', crash)
        with pytest.raises(OSError):
            w.import_archive(raw, check, KEY, observed_ms=START+DAY)
    with pytest.raises(ValueError, match='UNCOMMITTED_OR_MISSING_ROWS'):
        w.report()


def test_platform_independent_canonical_snapshot(tmp_path):
    """Same immutable bytes must produce the same digest on both CI systems."""
    from io import BytesIO
    from zipfile import ZipFile, ZipInfo, ZIP_STORED
    raw, _ = fixture(count=15)
    with ZipFile(BytesIO(raw)) as archive:
        member = archive.read(archive.namelist()[0])
    info = ZipInfo(KEY.rsplit('/', 1)[1][:-4]+'.csv', date_time=(1980, 1, 1, 0, 0, 0))
    info.create_system, info.external_attr = 0, 0x20
    out = BytesIO()
    with ZipFile(out, 'w', compression=ZIP_STORED) as archive:
        archive.writestr(info, member)
    raw = out.getvalue()
    check = (seal(raw)+'  '+KEY.rsplit('/', 1)[1]).encode()
    w = warehouse(tmp_path)
    with w.writer():
        w.import_archive(raw, check, KEY, observed_ms=START+DAY)
    assert w.report()['registry']['snapshot_sha256'] == 'f20ac5e8852b7a29501ec10f1d5eb420dc194fd03df11716c6d53b5aba1107a0'
